<?php
require_once 'common.php'; require_customer();
$cart=$_SESSION['cart']??[]; if(!$cart){header('Location: cart.php');exit();}
$ids=array_keys($cart);$place=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$stmt=$conn->prepare("SELECT product_id,product_name,price,stock FROM products WHERE product_id IN ($place)");$stmt->bind_param($types,...$ids);$stmt->execute();$result=$stmt->get_result();$items=[];$total=0;
while($p=$result->fetch_assoc()){$q=(int)$cart[$p['product_id']];if($q<1||$q>$p['stock']){header('Location: cart.php');exit();}$p['quantity']=$q;$p['subtotal']=$q*$p['price'];$total+=$p['subtotal'];$items[]=$p;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$address=trim($_POST['delivery_address']??'');$notes=trim($_POST['notes']??'');if($address===''){$error='Please enter your delivery address.';}else{$conn->begin_transaction();try{$stmt=$conn->prepare("INSERT INTO orders(customer_id,total_amount,delivery_address,notes) VALUES(?,?,?,?)");$stmt->bind_param('idss',$_SESSION['customer_id'],$total,$address,$notes);$stmt->execute();$order_id=$conn->insert_id;$stmt->close();$detail=$conn->prepare('INSERT INTO order_details(order_id,product_id,quantity,unit_price,subtotal) VALUES(?,?,?,?,?)');foreach($items as $item){$detail->bind_param('iiidd',$order_id,$item['product_id'],$item['quantity'],$item['price'],$item['subtotal']);$detail->execute();}$detail->close();$conn->commit();$_SESSION['cart']=[];header('Location: orders.php?placed='.$order_id);exit();}catch(Throwable $e){$conn->rollback();$error='Your order could not be submitted. Please try again.';}}}
$shop_title='Checkout';include 'header.php';
?>
<div class="section-head"><div><h2>Checkout</h2><p>Confirm your order details before submitting.</p></div></div>
<?php if($error): ?><div class="alert error"><?php echo shop_e($error); ?></div><?php endif; ?>
<div class="cart-layout"><div class="card-panel"><div class="panel-head"><h2>Order Details</h2></div><div style="padding:22px"><div class="order-lines"><?php foreach($items as $item): ?><div class="order-line"><span><?php echo shop_e($item['product_name']); ?> × <?php echo $item['quantity']; ?></span><strong>₱<?php echo number_format($item['subtotal'],2); ?></strong></div><?php endforeach; ?></div><form method="post" style="margin-top:25px"><div class="field"><label>Delivery Address <span style="color:#a62b20">*</span></label><textarea name="delivery_address" rows="3" required placeholder="House/Building No., Street, Barangay, Municipality/City, Province"><?php echo shop_e($_POST['delivery_address']??''); ?></textarea><small style="display:block;color:var(--muted);margin-top:6px">Enter the complete address where the order should be delivered.</small></div><div class="field"><label>Order Notes (optional)</label><textarea name="notes" rows="3" placeholder="Add delivery or order notes..."><?php echo shop_e($_POST['notes']??''); ?></textarea></div><button class="btn btn-dark" type="submit"><i class="fa-solid fa-paper-plane"></i> Place Order</button><a class="btn btn-outline" href="cart.php">Back to Cart</a></form></div></div><aside class="card-panel summary"><h2 style="font-size:17px;margin-top:0">Total</h2><div class="summary-row"><span>Subtotal</span><strong>₱<?php echo number_format($total,2); ?></strong></div><div class="summary-row summary-total"><span>Total</span><span>₱<?php echo number_format($total,2); ?></span></div><p style="font-size:11px;color:var(--muted);line-height:1.6">Your order starts as <strong>Pending</strong>. The bakeshop will confirm it before stock is deducted.</p></aside></div>
<?php include 'footer.php'; ?>
